import{_ as n,a0 as l,w as i,s as p,ao as f,I as s,x as o,a1 as r,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"微软将对应用商店中开源软件的收费进行限制 | LCTT x X-CMD","titleTemplate":false,"description":"微软将对应用商店中开源软件的收费进行限制 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"微软将对应用商店中开源软件的收费进行限制 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"微软将对应用商店中开源软件的收费进行限制 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220620 Microsoft To Charge For Available Open Source Software In Microsoft Store","title":"微软将对应用商店中开源软件的收费进行限制","tag":"202206","desc":""},"relativePath":"202206/20220620 Microsoft To Charge For Available Open Source Software In Microsoft Store.md","filePath":"[post].md"}'),u={name:"202206/20220620 Microsoft To Charge For Available Open Source Software In Microsoft Store.md"};function m(d,t,T,x,C,w){const e=l("Link");return i(),p("div",null,[t[15]||(t[15]=f('<h1 id="微软将对应用商店中开源软件的收费进行限制" tabindex="-1">微软将对应用商店中开源软件的收费进行限制 <a class="header-anchor" href="#微软将对应用商店中开源软件的收费进行限制" aria-label="Permalink to “微软将对应用商店中开源软件的收费进行限制”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202206/25/101648dlxnqxkaox00xc3l.jpg" alt=""></p><p>2022 年 6 月 16 日，微软更新了其应用商店的策略。其中一项禁止了发布者对开源或免费的软件收取费用，另一项则针对的是商店使用的不合理高价。如果你在过去几年中访问过微软应用商店，你可能已经注意到，它正在成为越来越多的开源和免费产品的所在地。如果原始开发者将应用程序和游戏上传到商店，这将是有益的，但情况并非如此，因为它们是由第三方上传的。</p><p>更糟糕的是，其中许多程序仅作为付费应用提供，而不是免费下载。换句话说，微软的客户必须付费才能购买应用商店的版本，而它们在其他地方是免费的！在应用商店中，免费版和付费版有时并存。为免费应用付费已经够糟糕的了，但这并不是用户在购买时可能遇到的唯一问题。更新也可能是一个问题，因为山寨应用可能不会像源头应用程序那样频繁或快速地更新。</p><p>在更新的微软商店政策中，微软在 10.8.7 节下指出：</p><blockquote><p>在您决定产品或应用内购买的定价时，您的数字产品或服务的所有定价（包括销售或折扣）必须：</p><p>遵守所有适用的法律、法规和监管要求，包括联邦贸易委员会的《反欺骗性定价指南》。您不得试图从开源软件或其他可免费获得的软件中获利，您的产品也不应提供一个（与它提供的特性和功能相比）过高的不合理定价。</p></blockquote><p>这个新策略在更新部分中得到了确认。如果开源和免费产品普遍免费提供，则它们不得在微软应用商店上出售，发布者也不得对其产品收取不合理的高价。开源和免费应用的开发者可以在微软应用商店上为其产品收费。例如，Paint.net 的开发者就是这样做的。如果微软强制执行这些策略，许多应用将从应用商店中删除。以前，开发者可以向微软报告应用程序，但在新策略下，微软可以直接控制应用的列出和提交。</p><hr>',8)),s("p",null,[t[1]||(t[1]=o("via: ",-1)),r(e,{href:"https://www.opensourceforu.com/2022/06/microsoft-to-charge-for-available-open-source-software-in-microsoft-store/"},{default:a(()=>[...t[0]||(t[0]=[o("https://www.opensourceforu.com/2022/06/microsoft-to-charge-for-available-open-source-software-in-microsoft-store/",-1)])]),_:1})]),s("p",null,[t[6]||(t[6]=o("作者：",-1)),r(e,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:a(()=>[...t[2]||(t[2]=[o("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=o(" 选题：",-1)),r(e,{href:"https://github.com/lkxed"},{default:a(()=>[...t[3]||(t[3]=[o("lkxed",-1)])]),_:1}),t[8]||(t[8]=o(" 译者：",-1)),r(e,{href:"https://github.com/lkxed"},{default:a(()=>[...t[4]||(t[4]=[o("lkxed",-1)])]),_:1}),t[9]||(t[9]=o(" 校对：",-1)),r(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[5]||(t[5]=[o("wxy",-1)])]),_:1})]),s("p",null,[t[12]||(t[12]=o("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[10]||(t[10]=[o("LCTT",-1)])]),_:1}),t[13]||(t[13]=o(" 原创编译，",-1)),r(e,{href:"https://linux.cn/"},{default:a(()=>[...t[11]||(t[11]=[o("Linux中国",-1)])]),_:1}),t[14]||(t[14]=o(" 荣誉推出",-1))])])}const k=n(u,[["render",m]]);export{b as __pageData,k as default};
